import importlib.util
import os
import sys
import tempfile
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def _load(name: str, path: str):
    spec = importlib.util.spec_from_file_location(name, ROOT / path)
    mod = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = mod
    spec.loader.exec_module(mod)
    return mod


guest_netplan = _load("guest_netplan", "lib/guest_netplan.py")


STATIC_DEBIAN = """\
# generated by cloud-init
network:
  version: 2
  ethernets:
    eth0:
      addresses: [10.0.0.5/24]
      routes:
        - to: default
          via: 10.0.0.1
      nameservers:
        addresses: [10.0.0.1]
"""

DHCP_UBUNTU = """\
network:
  version: 2
  ethernets:
    ens3:
      dhcp4: true
"""

BOND_BAD = """\
network:
  version: 2
  bonds:
    bond0:
      interfaces: [eth0]
  ethernets:
    eth0: {}
"""


class GuestNetplanTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.root = Path(self.tmp)
        self.env = os.environ.copy()
        os.environ["PVEOSI_GUEST_ROOT"] = str(self.root)
        os.environ["PVEOSI_GUEST_MOCK_CMD"] = "1"
        (self.root / "etc/netplan").mkdir(parents=True)
        (self.root / "var/lib/pveosi-guest-setup/backups").mkdir(parents=True)

    def tearDown(self):
        os.environ.clear()
        os.environ.update(self.env)
        import shutil

        shutil.rmtree(self.tmp, ignore_errors=True)

    def _effective_file(self, content: str) -> None:
        ef = self.root / "netplan-effective.txt"
        ef.write_text(content, encoding="utf-8")
        os.environ["PVEOSI_GUEST_MOCK_NETPLAN_GET"] = f"file:{ef}"

    def test_static_debian_migration_preserves_bytes(self):
        src = self.root / "etc/netplan/50-cloud-init.yaml"
        src.write_text(STATIC_DEBIAN, encoding="utf-8")
        self._effective_file("eth0: {addresses: [10.0.0.5/24]}")
        result = guest_netplan.migrate_netplan_independence(dry_run=False)
        self.assertEqual(result["status"], "migrated")
        dest = self.root / "etc/netplan/90-pveosi-static.yaml"
        self.assertTrue(dest.is_file())
        self.assertEqual(dest.read_bytes(), src.read_bytes())
        self.assertFalse(src.exists())

    def test_dhcp_different_iface(self):
        (self.root / "etc/netplan/50-cloud-init.yaml").write_text(DHCP_UBUNTU, encoding="utf-8")
        self._effective_file("ens3 dhcp")
        plan = guest_netplan.build_netplan_plan()
        self.assertEqual(plan.action, "create_copy")

    def test_multiple_nics_refused(self):
        text = STATIC_DEBIAN + "    eth1:\n      dhcp4: true\n"
        (self.root / "etc/netplan/50-cloud-init.yaml").write_text(text, encoding="utf-8")
        with self.assertRaises(guest_netplan.NetplanSafetyError):
            guest_netplan.inspect_netplan()

    def test_bond_refused(self):
        (self.root / "etc/netplan/50-cloud-init.yaml").write_text(BOND_BAD, encoding="utf-8")
        with self.assertRaises(guest_netplan.NetplanSafetyError):
            guest_netplan.inspect_netplan()

    def test_dest_exists_different_refused(self):
        (self.root / "etc/netplan/50-cloud-init.yaml").write_text(STATIC_DEBIAN, encoding="utf-8")
        (self.root / "etc/netplan/90-pveosi-static.yaml").write_text("network:\n  version: 2\n", encoding="utf-8")
        with self.assertRaises(guest_netplan.NetplanSafetyError):
            guest_netplan.build_netplan_plan()

    def test_already_independent_idempotent(self):
        src = self.root / "etc/netplan/50-cloud-init.yaml"
        src.write_text(STATIC_DEBIAN, encoding="utf-8")
        dest = self.root / "etc/netplan/90-pveosi-static.yaml"
        dest.write_text(STATIC_DEBIAN, encoding="utf-8")
        plan = guest_netplan.build_netplan_plan()
        self.assertEqual(plan.action, "already_independent")

    def test_symlink_refused(self):
        real = self.root / "etc/netplan/50-cloud-init.yaml"
        real.write_text(STATIC_DEBIAN, encoding="utf-8")
        (self.root / "etc/netplan/51-link.yaml").symlink_to(real)
        with self.assertRaises(guest_netplan.NetplanSafetyError):
            guest_netplan.list_netplan_files()

    def test_invalid_yaml_refused(self):
        (self.root / "etc/netplan/50-cloud-init.yaml").write_text("network: [", encoding="utf-8")
        with self.assertRaises(guest_netplan.NetplanSafetyError):
            guest_netplan.inspect_netplan()

    def test_effective_mismatch_rolls_back(self):
        from unittest import mock

        (self.root / "etc/netplan/50-cloud-init.yaml").write_text(STATIC_DEBIAN, encoding="utf-8")
        with mock.patch.object(
            guest_netplan,
            "netplan_get_effective",
            side_effect=["before-config", "after-different"],
        ):
            with self.assertRaises(guest_netplan.NetplanSafetyError):
                guest_netplan.migrate_netplan_independence(dry_run=False)
        self.assertTrue((self.root / "etc/netplan/50-cloud-init.yaml").exists())
        self.assertFalse((self.root / "etc/netplan/90-pveosi-static.yaml").exists())

    def test_dry_run_no_files(self):
        (self.root / "etc/netplan/50-cloud-init.yaml").write_text(STATIC_DEBIAN, encoding="utf-8")
        guest_netplan.migrate_netplan_independence(dry_run=True)
        self.assertTrue((self.root / "etc/netplan/50-cloud-init.yaml").exists())
        self.assertFalse((self.root / "etc/netplan/90-pveosi-static.yaml").exists())

    def test_no_netplan_apply_in_mock_log(self):
        log = self.root / "cmds.json"
        os.environ["PVEOSI_GUEST_MOCK_SCRIPT"] = str(log)
        (self.root / "etc/netplan/50-cloud-init.yaml").write_text(STATIC_DEBIAN, encoding="utf-8")
        self._effective_file("same")
        guest_netplan.migrate_netplan_independence(dry_run=False)
        if log.exists():
            text = log.read_text(encoding="utf-8")
            self.assertNotIn("netplan apply", text)


if __name__ == "__main__":
    unittest.main()
